// Original NROM diagnostic, authored for these tests. No game ROM is bundled.
// A checkerboard changes color every ~quarter second. A holds red, Right blue.
// A also enables a square tone, so the same program exercises the NES APU.
export function inputROM() {
  const program = [], labels = new Map(), fixes = [];
  const emit = (...bytes) => program.push(...bytes);
  const label = name => labels.set(name, program.length);
  const branch = (op, name) => { emit(op, 0); fixes.push([program.length - 1, name, true]); };
  const address = (op, name) => { emit(op, 0, 0); fixes.push([program.length - 2, name, false]); };
  emit(0x78, 0xd8, 0xa2, 0xff, 0x9a, 0xe8); // SEI CLD LDX #ff TXS INX
  for (const register of [0x2000, 0x2001, 0x4010]) emit(0x8e, register & 255, register >> 8);
  for (const name of ['vblank1','vblank2']) { label(name); emit(0x2c, 0x02, 0x20); branch(0x10, name); }
  emit(0xa9, 0x3f, 0x8d, 0x06, 0x20, 0xa9, 0, 0x8d, 0x06, 0x20, 0xa2, 0);
  label('palette'); address(0xbd, 'colors'); emit(0x8d, 0x07, 0x20, 0xe8, 0xe0, 32); branch(0xd0, 'palette');
  emit(0xa9, 0x20, 0x8d, 0x06, 0x20, 0xa9, 0, 0x8d, 0x06, 0x20, 0xa0, 4, 0xa2, 0, 0xa9, 1);
  label('tiles'); emit(0x8d, 0x07, 0x20, 0xe8); branch(0xd0, 'tiles'); emit(0x88); branch(0xd0, 'tiles');
  emit(0xa9, 0, 0x85, 0, 0x8d, 0x05, 0x20, 0x8d, 0x05, 0x20);
  emit(0xa9, 0xbf, 0x8d, 0, 0x40, 0xa9, 0xfd, 0x8d, 2, 0x40, 0xa9, 8, 0x8d, 3, 0x40);
  emit(0xa9, 0x0a, 0x8d, 1, 0x20);
  label('loop'); emit(0x2c, 2, 0x20); branch(0x10, 'loop');
  emit(0xe6, 0, 0xa9, 1, 0x8d, 0x16, 0x40, 0xa9, 0, 0x8d, 0x16, 0x40, 0x85, 1, 0xa2, 8);
  label('buttons'); emit(0xad, 0x16, 0x40, 0x4a, 0x66, 1, 0xca); branch(0xd0, 'buttons');
  emit(0xa5, 1, 0x29, 1, 0x8d, 0x15, 0x40); branch(0xf0, 'right'); emit(0xa9, 8, 0x8d, 3, 0x40, 0xa9, 0x16); address(0x4c, 'paint');
  label('right'); emit(0xa5, 1, 0x29, 0x80); branch(0xf0, 'cycle'); emit(0xa9, 0x21); address(0x4c, 'paint');
  label('cycle'); emit(0xa5, 0, 0x4a, 0x4a, 0x4a, 0x4a, 0x29, 3, 0xaa); address(0xbd, 'cycleColors');
  label('paint'); emit(0x48, 0xa9, 0x3f, 0x8d, 6, 0x20, 0xa9, 1, 0x8d, 6, 0x20, 0x68, 0x8d, 7, 0x20);
  emit(0xa9, 0, 0x8d, 0, 0x20, 0x8d, 5, 0x20, 0x8d, 5, 0x20); address(0x4c, 'loop');
  label('colors'); for (let i = 0; i < 8; i++) emit(0x0f, 0x2a, 0x30, 0x12);
  label('cycleColors'); emit(0x2a, 0x28, 0x24, 0x21);
  for (const [offset, name, relative] of fixes) {
    const value = labels.get(name);
    if (relative) {
      const delta = value - offset - 1;
      if (delta < -128 || delta > 127) throw Error('Branch too far');
      program[offset] = delta & 255;
    } else { program[offset] = (0x8000 + value) & 255; program[offset + 1] = (0x8000 + value) >> 8; }
  }
  const bytes = new Uint8Array(16 + 16384 + 8192);
  bytes.set([0x4e, 0x45, 0x53, 0x1a, 1, 1]); bytes.set(program, 16);
  for (const vector of [0x3ffa, 0x3ffc, 0x3ffe]) bytes.set([0, 0x80], 16 + vector);
  for (let y = 0; y < 8; y++) bytes[16 + 16384 + 16 + y] = y < 4 ? 0xf0 : 0x0f;
  return bytes;
}
